conditionals.code:
int x = 10;
if (x > 0) {
  print('Positive');
} else {
  print('Non-positive');
}

// Pattern matching in switches (Dart 3.0+)
String desc = switch(x) {
  > 0 => 'Positive',
  _ => 'Other'
};

